(7631219, 1236877, 135744, '<td valign="top">Great to see you have met some local sheep on your travels.</td>', 'Great to see you have met some local sheep on your travels.', '2019-05-29 03:29:30.000000', NULL, 0),
(7631224, 1236876, 67145, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by P-A-U-L:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roz:</b></div><hr/><i> so beautiful .. <br/>congrats on the red in a challenge that had quite a few ''winners''  .. !! .. <br/>so what''s the go with one white chick and the rest grey .. ?? .. </i></td></tr></table> <br/> <br/>Thank you very much for your wonderful comments (as always)<br/> <br/>In answer to your question, I think it is just how the light is falling on the chick and also it may be just sticking its head out from the mother. This other photo from the same shoot helps illustrate this<br/> <br/><a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1237188" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/135000-139999/135744/120/Copyrighted_Image_Reuse_Prohibited_1237188.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/135000-139999/135744/120/Copyrighted_Image_Reuse_Prohibited_1237188.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/135000-139999/135744/120/Copyrighted_Image_Reuse_Prohibited_1237188.jpg"/></a> </i></td></tr></table> <br/> <br/>thanks Paul for clearing that up .. it actually made this photo even more special that one white chick .. :)<br/>also they might develop at different rates .. and come out grey and go white with time ... ??<br/> <br/>so of course i had to google it ..<br/>a few minutes later .. here''s what i found .. <br/><i>"Newly hatched cygnets are grey. They soon become brown and then, gradually, begin to turn white. The cob takes exception to white birds, other than his mate, on the territory and his own offspring are no exceptions."</i></td>', 'Originally posted by P-A-U-L: Originally posted by roz: so beautiful .. congrats on the red in a challenge that had quite a few ''winners''  .. !! .. so what''s the go with one white chick and the rest grey .. ?? ..   Thank you very much for your wonderful comments (as always) In answer to your question, I think it is just how the light is falling on the chick and also it may be just sticking its head out from the mother. This other photo from the same shoot helps illustrate this    thanks Paul for clearing that up .. it actually made this photo even more special that one white chick .. :)also they might develop at different rates .. and come out grey and go white with time ... ?? so of course i had to google it ..a few minutes later .. here''s what i found .. "Newly hatched cygnets are grey. They soon become brown and then, gradually, begin to turn white. The cob takes exception to white birds, other than his mate, on the territory and his own offspring are no exceptions."', '2019-05-29 06:19:11.000000', NULL, 0),
(7631225, 1236902, 67145, '<td valign="top">many congrats on your ribbon for this adorable image .. <br/>there are a few animal whisperers here in dpc ..  i think you may be the bunny whisperer .. <br/>which makes a lot of sense as they appear to be sleeping .. lol .. ;)<br/> <br/><i>edit to say ..</i> well one is sleeping ... the other one looks sleepy .. !! ..;)<br/><br/><i>Message edited by author 2019-05-29 05:23:49.</i></td>', 'many congrats on your ribbon for this adorable image .. there are a few animal whisperers here in dpc ..  i think you may be the bunny whisperer .. which makes a lot of sense as they appear to be sleeping .. lol .. ;) edit to say .. well one is sleeping ... the other one looks sleepy .. !! ..;)', '2019-05-29 06:22:45.000000', '2019-05-29 06:23:49.000000', 0),
(7631226, 1236950, 67145, '<td valign="top">oh .. i thought i had congratulated you on this wonderful image and your near ribbon in the challenge .. <br/>CONGRATULATIONS ..!!.. <br/>it looks even better bigger than what we see during the challenge .. <br/>such impact .. WOW .. !! .. :)</td>', 'oh .. i thought i had congratulated you on this wonderful image and your near ribbon in the challenge .. CONGRATULATIONS ..!!.. it looks even better bigger than what we see during the challenge .. such impact .. WOW .. !! .. :)', '2019-05-29 06:26:02.000000', NULL, 0),
(7631227, 1236663, 67145, '<td valign="top">this is wonderful .. !!! .. <br/>such an endearing image ... this is what babies are all about .. being nurtured .. <br/>congrats on showing us this beautiful moment .. <br/>even if messy .. lol .. ;)</td>', 'this is wonderful .. !!! .. such an endearing image ... this is what babies are all about .. being nurtured .. congrats on showing us this beautiful moment .. even if messy .. lol .. ;)', '2019-05-29 06:27:54.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7631228, 1236876, 135744, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roz:</b></div><hr/><i> <br/> <br/>thanks Paul for clearing that up .. it actually made this photo even more special that one white chick .. :)<br/>also they might develop at different rates .. and come out grey and go white with time ... ??<br/> <br/>so of course i had to google it ..<br/>a few minutes later .. here''s what i found .. <br/><i>"Newly hatched cygnets are grey. They soon become brown and then, gradually, begin to turn white. The cob takes exception to white birds, other than his mate, on the territory and his own offspring are no exceptions."</i> </i></td></tr></table> <br/> <br/>These cygnets were born on the day I was there - you can see the remnants of the one of the eggs on the left. I did take some photos of some cygnets I had seen 2 weeks previously when they were born so I will check my photos of those to see how much they have changed in the 2 weeks. I could have spent the whole day there photographing them but I was with my kids and they were very impatient so I was lucky to get some good photos.</td>', 'Originally posted by roz:  thanks Paul for clearing that up .. it actually made this photo even more special that one white chick .. :)also they might develop at different rates .. and come out grey and go white with time ... ?? so of course i had to google it ..a few minutes later .. here''s what i found .. "Newly hatched cygnets are grey. They soon become brown and then, gradually, begin to turn white. The cob takes exception to white birds, other than his mate, on the territory and his own offspring are no exceptions."   These cygnets were born on the day I was there - you can see the remnants of the one of the eggs on the left. I did take some photos of some cygnets I had seen 2 weeks previously when they were born so I will check my photos of those to see how much they have changed in the 2 weeks. I could have spent the whole day there photographing them but I was with my kids and they were very impatient so I was lucky to get some good photos.', '2019-05-29 06:44:55.000000', NULL, 0),
